import unittest
from unittest.mock import patch

from shop.bundles import BUNDLES, apply_bundles, bundle_savings


class BundlesTest(unittest.TestCase):
    def test_definitions(self):
        self.assertEqual(BUNDLES, {
            'STARTER': ('Starter pack', {'MUG': 1, 'TEE': 1}, 3299),
            'TRAVEL': ('Travel set', {'CAP': 1, 'BAG': 1}, 2099),
        })

    def test_savings(self):
        self.assertEqual(bundle_savings('STARTER'), 450)
        self.assertEqual(bundle_savings('TRAVEL'), 399)

    def test_empty_cart(self):
        self.assertEqual(apply_bundles({}), ({}, {}))

    def test_incomplete_bundles(self):
        items = {'MUG': 2, 'BAG': 1}
        self.assertEqual(apply_bundles(items), ({}, items))

    def test_exact_bundles(self):
        self.assertEqual(
            apply_bundles({'MUG': 1, 'TEE': 1, 'CAP': 1, 'BAG': 1}),
            ({'STARTER': 1, 'TRAVEL': 1}, {}),
        )

    def test_repeated_bundles_and_leftovers(self):
        items = {'MUG': 3, 'TEE': 2, 'CAP': 2, 'BAG': 4}
        original = items.copy()
        self.assertEqual(
            apply_bundles(items),
            ({'STARTER': 2, 'TRAVEL': 2}, {'MUG': 1, 'BAG': 2}),
        )
        self.assertEqual(items, original)

    def test_zero_quantities_are_omitted(self):
        self.assertEqual(apply_bundles({'MUG': 0, 'TEE': 1}), ({}, {'TEE': 1}))

    def test_alphabetical_priority_and_component_quantities(self):
        definitions = {
            'Z': ('Last', {'MUG': 1, 'CAP': 1}, 2000),
            'A': ('First', {'MUG': 2, 'TEE': 1}, 4000),
        }
        with patch('shop.bundles.BUNDLES', definitions):
            bundles, rest = apply_bundles({'MUG': 5, 'TEE': 3, 'CAP': 2})
            self.assertEqual(bundles, {'A': 2, 'Z': 1})
            self.assertEqual(list(bundles), ['A', 'Z'])
            self.assertEqual(rest, {'TEE': 1, 'CAP': 1})
            self.assertEqual(bundle_savings('A'), 999)


if __name__ == '__main__':
    unittest.main()

